SELECT "Generico_5"."Vehiculo" AS "Vehiculo",   CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Generico_5" WHERE ((CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) <= 2015) AND ("Generico_5"."Anunciante" IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND ("Generico_5"."Medio" = 'TELEVISION NACIONAL')) GROUP BY "Generico_5"."Vehiculo", "mn_FECHA_ok", "yr_FECHA_ok";
